{"cards": [{"node_code": "N_0f9758baf42ee08c", "definition": "研究液压系统中动力元件（泵、马达、阀）的工作原理、结构设计与性能参数，以及由这些元件构成的液压传动回路拓扑与控制逻辑。", "boundary": "聚焦于以液压油为介质的动力源、执行器及控制阀的选型、设计与回路集成。涵盖定量/变量泵、液压马达、方向/压力/流量阀及典型回路（如差动、平衡回路）。不涉及气动元件、真空系统或纯机械传动件。", "includes": ["液压泵、马达、控制阀的结构、原理及性能参数设计", "液压传动回路拓扑设计、压力/流量控制逻辑及系统联调", "液压元件的失效模式分析及可靠性设计"], "excludes": ["气动元件、真空装置及以压缩空气为介质的传动系统（归气动节点）", "液压缸、气缸等执行元件的具体尺寸计算与选型（归执行元件节点）", "液压过滤、油箱、蓄能器等辅助装置的设计（归辅助元件节点）"], "sibling_distinctions": [{"other_code": "N_8c3227a3bc11af4c", "rule": "本节点工作介质为液压油，侧重高压、大功率及精密控制；兄弟节点工作介质为气体，侧重低压、快速响应及真空应用。"}, {"other_code": "N_9cfa4155c539bd78", "rule": "本节点侧重动力源（泵/马达）与控制阀（阀）及回路逻辑；兄弟节点侧重执行元件（缸）的受力分析与尺寸设计。"}, {"other_code": "N_6cd3245882dbd227", "rule": "本节点侧重核心动力与控制元件及主回路；兄弟节点侧重过滤、冷却、油箱等辅助支持系统。"}], "cross_boundary_rule": "涉及电液伺服时，若侧重阀与泵的流体控制特性归本节点，若侧重电机驱动与控制算法归控制节点；涉及液压马达时，若侧重流体动力传递归本节点，若侧重电机本体设计归电机节点。"}, {"node_code": "N_8c3227a3bc11af4c", "definition": "研究利用压缩空气或真空作为工作介质，通过气动元件实现动力传递、控制与执行的系统，涵盖气动元件、回路设计及真空传动技术。", "boundary": "聚焦于以气体为介质的传动与控制。包括气缸、气马达、气动阀、真空吸盘等元件的设计与选型，以及气动回路逻辑、真空发生与维持技术。不涉及液压系统或纯机械传动。", "includes": ["气动执行元件（气缸、气马达）与控制元件（阀、接头）的设计", "气动传动回路设计、逻辑控制及真空传动系统原理", "气动系统的能效分析、噪声控制及安全设计"], "excludes": ["液压动力元件、回路及以液压油为介质的传动系统（归液压节点）", "纯机械传动件（如齿轮、链条）的设计（归机械传动节点）", "气动元件的微观材料疲劳研究（归材料或可靠性节点）"], "sibling_distinctions": [{"other_code": "N_0f9758baf42ee08c", "rule": "本节点工作介质为气体，侧重低压、快速响应及真空应用；兄弟节点工作介质为液体，侧重高压、大功率及精密控制。"}, {"other_code": "N_9cfa4155c539bd78", "rule": "本节点涵盖气动执行元件及真空系统整体；兄弟节点侧重液压/气动执行元件的通用参数计算，若侧重真空特有结构归本节点。"}], "cross_boundary_rule": "涉及气动马达时，若侧重气体动力传递归本节点，若侧重电机本体设计归电机节点；涉及气动控制时，若侧重阀与回路归本节点，若侧重PLC/传感器控制归控制节点。"}, {"node_code": "N_395f23ee61982d75", "definition": "研究液压与气动传动系统的整体架构设计、性能优化及能效管理，涵盖系统级仿真、热管理、噪声控制及节能策略。", "boundary": "聚焦于流体动力传动系统的宏观设计与性能评估。包括系统拓扑优化、压力/流量匹配、热平衡计算、能效分析及噪声/振动控制。不涉及具体元件的微观结构设计或纯机械传动。", "includes": ["液压/气动系统整体架构设计、仿真建模及性能优化", "系统能效分析、热管理、噪声控制及节能策略", "流体动力系统的可靠性评估及失效模式分析"], "excludes": ["液压/气动具体元件（泵、阀、缸）的微观结构设计（归元件节点）", "纯机械传动系统（齿轮、带链）的能效分析（归机械传动节点）", "纯热力学循环中的流体机械（如涡轮机）设计（归热流体节点）"], "sibling_distinctions": [{"other_code": "N_0f9758baf42ee08c", "rule": "本节点侧重系统级性能、能效与热管理；兄弟节点侧重液压元件及回路的具体设计与控制逻辑。"}, {"other_code": "N_8c3227a3bc11af4c", "rule": "本节点侧重系统级性能、能效与热管理；兄弟节点侧重气动元件及真空系统的具体设计与控制逻辑。"}, {"other_code": "N_6cd3245882dbd227", "rule": "本节点侧重系统整体能效与热平衡；兄弟节点侧重过滤、污染控制等辅助元件的具体设计。"}], "cross_boundary_rule": "涉及系统仿真时，若侧重流体动力特性归本节点，若侧重控制算法归控制节点；涉及能效优化时，若侧重流体回路设计归本节点，若侧重电机效率归电机节点。"}]}
